// A stand-in for an installed package that creates its own emitters.
const { EventEmitter } = require('node:events');

class LibClient extends EventEmitter {
  constructor() {
    super();
    // The package listens to itself, as most do.
    this.on('tick', function libOnTick() {});
  }
  tick() { this.emit('tick', 1); }
}

function makeBus() {
  const bus = new EventEmitter();
  bus.on('ping', function libOnPing() {});
  return bus;
}

module.exports = { LibClient, makeBus };
